"use client";
import { useState, type ReactNode } from "react";
import priceFormat from "@/helpers/priceFormat";
import WishlistButton from "@/components/wishlist/wishlist-button";
import { isPopularTour } from "@/data/popularTours";
import RouteModal from "./route-modal";
import CardGallery from "./card-gallery";
import styles from "./listing-card.module.scss";

// Minimal inline icons matching the reference design's stroke style.
function MetaIcon({ name }: { name: "clock" | "map" | "pin" }) {
  const paths: Record<string, ReactNode> = {
    clock: (
      <>
        <circle cx="12" cy="12" r="9" />
        <path d="M12 7v5l3 2" />
      </>
    ),
    map: (
      <>
        <path d="M9 3 3 6v15l6-3 6 3 6-3V3l-6 3-6-3z" />
        <path d="M9 3v15" />
        <path d="M15 6v15" />
      </>
    ),
    pin: (
      <>
        <path d="M12 22s7-7.5 7-13a7 7 0 1 0-14 0c0 5.5 7 13 7 13z" />
        <circle cx="12" cy="9" r="2.5" />
      </>
    ),
  };
  return (
    <svg
      width={13}
      height={13}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.6}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
    >
      {paths[name]}
    </svg>
  );
}

export default function ListingCard({
  detail,
  priceLoading,
  priceInfo = {
    price: 0,
    oldPrice: 0,
    paxLeft: 0,
    currency: "",
  },
  priority = false,
}: {
  detail: any;
  priceLoading: boolean;
  priceInfo?: {
    price: number;
    oldPrice: number;
    paxLeft: number;
    currency: string;
  };
  priority?: boolean;
}) {
  const tourLink = `/tour/${detail.slug}`;

  const [routeOpen, setRouteOpen] = useState(false);

  const hasDiscount =
    !priceLoading &&
    priceInfo &&
    priceInfo.oldPrice > 0 &&
    priceInfo.price !== priceInfo.oldPrice;

  const discountPct = hasDiscount
    ? Math.round(
        ((priceInfo.oldPrice - priceInfo.price) / priceInfo.oldPrice) * 100,
      )
    : 0;

  const durationLabel =
    detail.defaults?.duration?.days === 1
      ? "Daily"
      : `${detail.defaults?.duration?.days} Days`;

  const destinationsCount = detail.routes?.length ?? 0;


  return (
    <article className={styles.lcard}>
      <a
        href={tourLink}
        title={detail.name}
        target="_blank"
        className={styles.img}
      >
        <CardGallery detail={detail} priority={priority} />
        {hasDiscount && discountPct > 0 && (
          <span className={`${styles.tag} ${styles.deal}`}>
            {discountPct}% Off
          </span>
        )}
      </a>
      <WishlistButton
        tour={{
          id: detail.id,
          slug: detail.slug,
          name: detail.name,
          image: detail.image,
        }}
        className={styles.like}
      />

      <div className={styles.body}>
        <div className={styles.badges}>
          {detail.reviews_count > 0 && detail.rating > 0 && (
            <span className={styles.rating}>
              <svg
                className={styles.star}
                width={12}
                height={12}
                viewBox="0 0 24 24"
                fill="currentColor"
                aria-hidden="true"
              >
                <path d="M12 2l2.9 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77 5.82 21l1.18-6.88-5-4.87 6.91-1.01L12 2z" />
              </svg>
              <span className={styles.ratingValue}>
                {Number(detail.rating).toFixed(1)}
              </span>
              <span className={styles.ratingCount}>
                ({detail.reviews_count})
              </span>
            </span>
          )}
          {isPopularTour(detail.id) && (
            <span className={`${styles.badge} ${styles.popular}`}>
              <span aria-hidden="true">🔥</span>
              Popular
            </span>
          )}
          <span className={`${styles.badge} ${styles.good}`}>
            <svg
              width={12}
              height={12}
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth={1.8}
              strokeLinecap="round"
              strokeLinejoin="round"
              aria-hidden="true"
            >
              <circle cx="12" cy="12" r="9" />
              <path d="M9 12l2 2 4-4" />
            </svg>
            Free Cancellation
          </span>
        </div>

        <h3 className={styles.title}>
          <a href={tourLink} title={detail.name} target="_blank">
            {detail.name}
          </a>
        </h3>

        <div className={styles.meta}>
          {detail.defaults?.duration?.days != null && (
            <span>
              <MetaIcon name="clock" /> {durationLabel}
            </span>
          )}
          {destinationsCount > 0 && (
            <button
              type="button"
              className={styles.destBtn}
              onClick={() => setRouteOpen(true)}
              aria-label={`${destinationsCount} ${
                destinationsCount === 1 ? "destination" : "destinations"
              } — click to view the route on the map`}
            >
              <MetaIcon name="map" /> {destinationsCount}{" "}
              {destinationsCount === 1 ? "Destination" : "Destinations"}
              <span className={styles.destTip} role="tooltip" aria-hidden="true">
                Click to view the route on the map
              </span>
            </button>
          )}
          {detail.startLocation && (
            <span>
              <MetaIcon name="pin" /> {detail.startLocation}
            </span>
          )}
        </div>

        <div className={styles.footer}>
          {priceLoading ? (
            <span className="tw-block tw-h-3.5 tw-w-[110px] tw-rounded tw-bg-[#eef0f3] tw-animate-pulse" />
          ) : (
            priceInfo &&
            priceInfo.price > 0 && (
              <div className={styles.price}>
                {hasDiscount && (
                  <span className={styles.was}>
                    {priceFormat({
                      amount: priceInfo.oldPrice,
                      currency: priceInfo.currency,
                    })}
                  </span>
                )}
                <span className={styles.from}>from</span>
                <span className={styles.amt}>
                  {priceFormat({
                    amount: priceInfo.price,
                    currency: priceInfo.currency,
                  })}
                </span>
              </div>
            )
          )}
          <a
            href={tourLink}
            title={detail.name}
            target="_blank"
            role="button"
            className={`tw-inline-flex tw-items-center tw-justify-center tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-border-0 tw-cursor-pointer tw-no-underline tw-transition-colors ${styles.cta}`}
          >
            View Tour
          </a>
        </div>
      </div>

      {/* Mounted only while open → Google Maps JS is fetched on first click,
          never on page load (keeps us inside the Maps API quota). */}
      {routeOpen && (
        <RouteModal
          tour={{
            id: detail.id,
            slug: detail.slug,
            name: detail.name,
            image: detail.image,
            durationDays: detail.defaults?.duration?.days,
          }}
          routes={detail.routes}
          onClose={() => setRouteOpen(false)}
        />
      )}
    </article>
  );
}
