"use client";
import { useEffect, useMemo, useState } from "react";
import { getCookie, hasCookie } from "cookies-next";
import ReCAPTCHA from "react-google-recaptcha";
import Select from "react-select";
import getUserDetail from "@/services/auth/userDetail";
import getLocations from "@/services/locations";
import sendMessage from "@/services/enquiryService";
import styles from "./route-modal.module.scss";

// react-select styled to match the modal's rounded, brand-focused fields.
const phoneSelectStyles = {
  control: (base: any, state: any) => ({
    ...base,
    minHeight: 44,
    borderRadius: 10,
    borderColor: state.isFocused ? "#854ec9" : "#e2dcec",
    boxShadow: state.isFocused ? "0 0 0 3px rgba(133,78,201,0.15)" : "none",
    "&:hover": { borderColor: state.isFocused ? "#854ec9" : "#cdb6ec" },
    fontSize: 14,
  }),
  valueContainer: (base: any) => ({ ...base, padding: "2px 10px" }),
  menu: (base: any) => ({ ...base, borderRadius: 10, overflow: "hidden" }),
  menuPortal: (base: any) => ({ ...base, zIndex: 100001 }),
  option: (base: any, state: any) => ({
    ...base,
    fontSize: 13.5,
    cursor: "pointer",
    backgroundColor: state.isSelected
      ? "#854ec9"
      : state.isFocused
        ? "#f5f0fc"
        : "#fff",
    color: state.isSelected ? "#fff" : "#14101c",
  }),
};

// Modern, in-pane version of tour-detail-page/inquiry-modal.tsx — same
// business logic (services, payload shape, reCAPTCHA), restyled to live inside
// the route modal's left pane instead of a stacked Bootstrap dialog.
export default function InquiryForm({
  tourId,
  onBack,
}: {
  tourId: number;
  onBack: () => void;
}) {
  const [isActiveUser, setIsActiveUser] = useState(false);
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [phoneCodeId, setPhoneCodeId] = useState<number | null>(null);
  const [phoneNumber, setPhoneNumber] = useState("");
  const [question, setQuestion] = useState("");
  const [recaptcha, setRecaptcha] = useState<string | null>(null);
  const [locations, setLocations] = useState<
    Array<{ id: number; name: string; phone_code?: string }>
  >([]);
  const [sending, setSending] = useState(false);
  const [sent, setSent] = useState(false);
  const [error, setError] = useState("");

  const phoneOptions = useMemo(
    () =>
      locations.map((l) => ({
        value: l.id,
        label: `${l.name} (${l.phone_code})`,
      })),
    [locations],
  );

  useEffect(() => {
    getLocations()
      .then((res: any) => {
        const list = Array.isArray(res) ? res : [];
        setLocations(
          list
            .filter((i: any) => i.phone_code && i.phone_code !== "")
            .sort((a: any, b: any) => (a.name < b.name ? -1 : 1)),
        );
      })
      .catch(() => setLocations([]));

    if (hasCookie("auth-token")) {
      getUserDetail({ token: getCookie("auth-token") })
        .then((res: any) => {
          setIsActiveUser(true);
          setName(res.name ?? "");
          setEmail(res.email ?? "");
        })
        .catch(() => {});
    }
  }, []);

  const submit = () => {
    if (!isActiveUser && (name.trim() === "" || email.trim() === "")) {
      setError("Please fill in the required fields.");
      return;
    }
    if (question.trim() === "") {
      setError("Please fill in the required fields.");
      return;
    }
    if (!isActiveUser && phoneNumber && !phoneCodeId) {
      setError("Please select your phone country code.");
      return;
    }
    if (!recaptcha) {
      setError("Please confirm robot verification.");
      return;
    }

    setError("");
    setSending(true);

    const payload: any = {
      tour_id: tourId,
      "g-recaptcha-response": recaptcha,
      message: question,
    };
    if (!isActiveUser) {
      payload.contact_name = name;
      payload.contact_email = email;
      if (phoneCodeId && phoneNumber) {
        payload.phone_code = phoneCodeId;
        payload.contact_phone = phoneNumber;
      }
    }

    sendMessage({ data: payload })
      .then(() => {
        setSending(false);
        setSent(true);
      })
      .catch((err: any) => {
        setSending(false);
        if (err && err.errors && typeof err.errors === "object") {
          const msgs = Object.values(err.errors)
            .map((m: any) => (Array.isArray(m) ? m.join(" ") : m))
            .join(" ");
          setError(msgs || "There is a problem. Please try again later.");
        } else {
          setError(err?.message || "There is a problem. Please try again later.");
        }
      });
  };

  return (
    <div className={styles.formPane}>
      <div className={styles.formHead}>
        <button
          type="button"
          className={styles.back}
          onClick={onBack}
          aria-label="Back to route"
        >
          <svg
            width={18}
            height={18}
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth={2}
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <path d="M15 18l-6-6 6-6" />
          </svg>
        </button>
        <h3 className={styles.formTitle}>Ask a Question</h3>
      </div>

      <div className={styles.formBody}>
        {sent ? (
          <div className={styles.formSuccess}>
            <div className={styles.successIcon}>
              <svg
                width={26}
                height={26}
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth={2}
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <path d="M20 6L9 17l-5-5" />
              </svg>
            </div>
            <p className="tw-mb-0">
              Your message has been delivered. We&apos;ll get back to you as soon
              as possible.
            </p>
          </div>
        ) : (
          <>
            <p className={styles.formIntro}>
              {isActiveUser && (
                <>
                  Hello <strong>{name}</strong>.{" "}
                </>
              )}
              Ask your question to the tour provider.
            </p>

            {error && <div className={styles.formError}>{error}</div>}

            {!isActiveUser && (
              <>
                <div className={styles.fieldRow}>
                  <div className={styles.field}>
                    <label className={styles.label}>
                      Name <span className={styles.req}>*</span>
                    </label>
                    <input
                      type="text"
                      className={styles.input}
                      placeholder="Your name"
                      value={name}
                      onChange={(e) => setName(e.target.value)}
                    />
                  </div>
                  <div className={styles.field}>
                    <label className={styles.label}>
                      Email <span className={styles.req}>*</span>
                    </label>
                    <input
                      type="email"
                      className={styles.input}
                      placeholder="you@example.com"
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                    />
                  </div>
                </div>
                <div className={styles.field}>
                  <label className={styles.label}>
                    Phone <span className={styles.optional}>(optional)</span>
                  </label>
                  <div className={styles.phoneRow}>
                    <div className={styles.phoneCode}>
                      <Select
                        instanceId="inquiry-phone-code"
                        options={phoneOptions}
                        value={
                          phoneOptions.find((o) => o.value === phoneCodeId) ??
                          null
                        }
                        onChange={(opt: any) =>
                          setPhoneCodeId(opt ? opt.value : null)
                        }
                        placeholder="Code"
                        aria-label="Country code"
                        isClearable
                        styles={phoneSelectStyles}
                        menuPlacement="auto"
                        menuPortalTarget={
                          typeof document !== "undefined"
                            ? document.body
                            : undefined
                        }
                        noOptionsMessage={() => "No match"}
                      />
                    </div>
                    <input
                      type="text"
                      inputMode="numeric"
                      className={styles.input}
                      placeholder="Number"
                      value={phoneNumber}
                      onChange={(e) =>
                        setPhoneNumber(e.target.value.replace(/\D/g, ""))
                      }
                    />
                  </div>
                </div>
              </>
            )}

            <div className={styles.field}>
              <label className={styles.label}>
                Your Question <span className={styles.req}>*</span>
              </label>
              <textarea
                className={styles.textarea}
                rows={3}
                placeholder="What would you like to know about this tour?"
                value={question}
                onChange={(e) => setQuestion(e.target.value)}
              />
            </div>

            <div className={styles.recaptcha}>
              <ReCAPTCHA
                sitekey="6LesOOIpAAAAAE1l4Z8q_ZVqpAGTnNaTRJTDzYxu"
                hl="en"
                onChange={(v) => setRecaptcha(v)}
                asyncScriptOnLoad={() => setRecaptcha(null)}
              />
            </div>

            {/* Button flows at the end of the scrollable form body (not a
                pinned footer): avoids the iOS Safari bug where a fixed-bottom
                control hides behind the toolbar/keyboard after input blur. */}
            <div className={styles.actions}>
              <button
                type="button"
                className={`tw-inline-flex tw-items-center tw-justify-center tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-border-0 tw-cursor-pointer tw-no-underline tw-transition-colors disabled:tw-opacity-60 disabled:tw-cursor-not-allowed ${styles.viewTour}`}
                onClick={submit}
                disabled={sending}
              >
                {sending ? (
                  <>
                    <span
                      className="tw-inline-block tw-w-4 tw-h-4 tw-mr-2 tw-rounded-full tw-border-2 tw-border-solid tw-border-current tw-border-r-transparent tw-animate-spin tw-align-[-0.125em]"
                      role="status"
                      aria-hidden="true"
                    />
                    Sending…
                  </>
                ) : (
                  "Send Message"
                )}
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}
