"use client";
import { useEffect, useMemo, useState } from "react";
import { createPortal } from "react-dom";
import dynamic from "next/dynamic";
import { useWishlist } from "@/components/wishlist/wishlist-context";
import cdnImage from "@/helpers/cdnImage";
import InquiryForm from "./inquiry-form";
import BrochureForm from "./brochure-form";
import type { RoutePoint } from "./route-map";
import getLocationParents, {
  type LocationCrumb,
} from "@/services/locationParentsClient";
import styles from "./route-modal.module.scss";

const HEART_PATH =
  "M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z";

type View = "route" | "inquiry" | "brochure";

// The Google Maps bundle is only imported (and the JS API only fetched) once
// this component mounts — i.e. once the user actually opens the modal. The
// parent unmounts <RouteModal> when closed, so nothing touches the Maps quota
// until a destination is tapped.
const RouteMap = dynamic(() => import("./route-map"), {
  ssr: false,
  loading: () => (
    <div className={styles.mapLoading}>
      <span
        className="tw-inline-block tw-w-4 tw-h-4 tw-mr-2 tw-rounded-full tw-border-2 tw-border-solid tw-border-current tw-border-r-transparent tw-animate-spin tw-align-[-0.125em]"
        role="status"
        aria-hidden="true"
      />
      Loading map…
    </div>
  ),
});

function toPoints(routes: any[]): RoutePoint[] {
  return (routes ?? [])
    .filter(
      (r) => r && Number.isFinite(Number(r.lat)) && Number.isFinite(Number(r.lng)),
    )
    // Preserve the curated journey order (pivot.order_sort) when present.
    .slice()
    .sort((a, b) => {
      const ao = a?.pivot?.order_sort ?? 0;
      const bo = b?.pivot?.order_sort ?? 0;
      return ao - bo;
    })
    .map((r) => ({
      id: r.id ?? null,
      name: r.name,
      lat: Number(r.lat),
      lng: Number(r.lng),
      type: r.type,
    }));
}

// Deep-link that opens the full multi-stop route in the real Google Maps app.
function googleMapsDirUrl(points: RoutePoint[]): string {
  if (points.length === 0) return "https://www.google.com/maps";
  if (points.length === 1) {
    const p = points[0];
    return `https://www.google.com/maps/search/?api=1&query=${p.lat},${p.lng}`;
  }
  const origin = points[0];
  const destination = points[points.length - 1];
  const waypoints = points
    .slice(1, -1)
    // Google caps the dir URL waypoints; 8 intermediate stops is plenty here.
    .slice(0, 8)
    .map((p) => `${p.lat},${p.lng}`)
    .join("|");
  const params = new URLSearchParams({
    api: "1",
    origin: `${origin.lat},${origin.lng}`,
    destination: `${destination.lat},${destination.lng}`,
    travelmode: "driving",
  });
  if (waypoints) params.set("waypoints", waypoints);
  return `https://www.google.com/maps/dir/?${params.toString()}`;
}

export default function RouteModal({
  tour,
  routes,
  onClose,
}: {
  tour: {
    id: number;
    slug: string;
    name: string;
    image?: string;
    durationDays?: number;
  };
  routes: any[];
  onClose: () => void;
}) {
  const tourName = tour.name;
  const tourLink = `/tour/${tour.slug}`;

  const [mounted, setMounted] = useState(false);
  const [focusIndex, setFocusIndex] = useState<number | null>(null);
  const [view, setView] = useState<View>("route");

  const { isFavorite, toggle, hydrated } = useWishlist();
  const saved = hydrated && isFavorite(tour.id);

  const points = useMemo(() => toPoints(routes), [routes]);
  const mapsUrl = useMemo(() => googleMapsDirUrl(points), [points]);

  // Durakların ata zinciri (Europe › Turkey › Istanbul) — tur detayındaki Route
  // bölümüyle aynı bilgi. Kart verisinde gelmediği için modal açılınca tek toplu
  // istekle çekilir; gelene kadar durak adı yalın gösterilir.
  const [crumbs, setCrumbs] = useState<Record<number, LocationCrumb[]>>({});

  // Portals need the DOM; only render after mount to stay SSR-safe.
  useEffect(() => setMounted(true), []);

  useEffect(() => {
    const ids = points.map((p) => p.id).filter(Boolean) as number[];
    if (ids.length === 0) return;

    let alive = true;
    getLocationParents(ids).then((resolved) => {
      if (alive) setCrumbs(resolved);
    });
    return () => {
      alive = false;
    };
  }, [points]);

  // Lock body scroll + close on Escape while open.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    document.addEventListener("keydown", onKey);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.removeEventListener("keydown", onKey);
      document.body.style.overflow = prev;
    };
  }, [onClose]);

  if (!mounted) return null;

  // Duration + destination count reads better than "Istanbul → Istanbul" for
  // the many round-trip tours whose start and end are the same place.
  const durationLabel =
    tour.durationDays == null
      ? ""
      : tour.durationDays === 1
        ? "Daily"
        : `${tour.durationDays} Days`;
  const destLabel =
    points.length > 0
      ? `${points.length} ${points.length === 1 ? "Destination" : "Destinations"}`
      : "";

  const closeButton = (
    <button
      type="button"
      className={styles.close}
      aria-label="Close"
      onClick={onClose}
    >
      <svg
        width={20}
        height={20}
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth={2}
        strokeLinecap="round"
      >
        <path d="M6 6l12 12M18 6L6 18" />
      </svg>
    </button>
  );

  // Tour context shown beside the form so the user never loses track of which
  // tour they're enquiring about.
  const infoPane = (
    <aside
      className={styles.infoPane}
      style={
        tour.image
          ? { backgroundImage: `url("${cdnImage(tour.image)}")` }
          : undefined
      }
    >
      <div className={styles.infoOverlay} />
      <div className={styles.infoContent}>
        <span className={styles.infoEyebrow}>You’re enquiring about</span>
        <h2 className={styles.infoTitle}>{tourName}</h2>
        {(durationLabel || destLabel) && (
          <p className={styles.infoMeta}>
            {durationLabel && (
              <span className={styles.infoMetaItem}>
                <svg
                  width={14}
                  height={14}
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth={1.8}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  aria-hidden="true"
                >
                  <circle cx="12" cy="12" r="9" />
                  <path d="M12 7v5l3 2" />
                </svg>
                {durationLabel}
              </span>
            )}
            {destLabel && (
              <span className={styles.infoMetaItem}>
                <svg
                  width={14}
                  height={14}
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth={1.8}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  aria-hidden="true"
                >
                  <path d="M9 3 3 6v15l6-3 6 3 6-3V3l-6 3-6-3z" />
                  <path d="M9 3v15M15 6v15" />
                </svg>
                {destLabel}
              </span>
            )}
          </p>
        )}
      </div>
    </aside>
  );

  return createPortal(
    <div
      className={styles.overlay}
      role="dialog"
      aria-modal="true"
      aria-label={`${tourName} — route`}
      onClick={onClose}
    >
      <div
        className={`${styles.dialog} ${view !== "route" ? styles.formView : ""}`}
        onClick={(e) => e.stopPropagation()}
      >
        {closeButton}

        {/* The route view (map + itinerary) stays mounted across view changes:
            unmounting/remounting the Google Map crashes @react-google-maps/api's
            IntersectionObserver. While a form is open it's hidden via .formView. */}
        <>
            {/* Map — full-bleed on the left */}
            <div className={styles.mapPane}>
              {points.length > 0 ? (
                <>
                  <RouteMap
                    points={points}
                    focusIndex={focusIndex}
                    active={view === "route"}
                  />
                  {/* Map-context action floating over the map (à la Google's
                      own embeds), keeping the action list uncluttered. */}
                  <a
                    href={mapsUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className={styles.mapAction}
                  >
                    <svg
                      width={15}
                      height={15}
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth={1.9}
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      aria-hidden="true"
                    >
                      <path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6" />
                      <path d="M15 3h6v6" />
                      <path d="M10 14L21 3" />
                    </svg>
                    Open in Google Maps
                  </a>
                </>
              ) : (
                <div className={styles.mapLoading}>No route data available.</div>
              )}
            </div>

            {/* Itinerary + actions */}
            <aside className={styles.listPane}>
              <div className={styles.intro}>
                {tour.image && (
                  // eslint-disable-next-line @next/next/no-img-element
                  <img
                    className={styles.introThumb}
                    src={cdnImage(tour.image)}
                    alt=""
                    loading="lazy"
                  />
                )}
                <div className={styles.introText}>
                  <h2 className={styles.title}>{tourName}</h2>
                </div>
              </div>

              <div className={styles.listScroll}>
                <div className={styles.listHead}>
                  <span className={styles.listHeadLabel}>Itinerary</span>
                  <span className={styles.listHeadCount}>
                    {points.length} {points.length === 1 ? "stop" : "stops"}
                  </span>
                </div>
                <ol className={styles.timeline}>
                  {points.map((p, i) => {
                    // Start/End only mean something on a real multi-stop route.
                    // A single-destination tour is just one neutral location.
                    const multi = points.length > 1;
                    const isStart = multi && i === 0;
                    const isEnd = multi && i === points.length - 1;
                    return (
                      <li
                        key={`${p.name}-${i}`}
                        className={`${styles.stop} ${
                          focusIndex === i ? styles.stopActive : ""
                        }`}
                      >
                        <button
                          type="button"
                          className={styles.stopBtn}
                          onClick={() => setFocusIndex(i)}
                          title={`Show ${p.name} on the map`}
                        >
                          <span
                            className={`${styles.dot} ${
                              isStart
                                ? styles.dotStart
                                : isEnd
                                  ? styles.dotEnd
                                  : ""
                            }`}
                          >
                            {i + 1}
                          </span>
                          <span className={styles.stopText}>
                            <span className={styles.stopName}>{p.name}</span>
                            {/* Where this place sits in the world: Europe › Turkey › Aydin */}
                            {p.id != null && (crumbs[p.id]?.length ?? 0) > 0 && (
                              <span className={styles.stopCrumbs}>
                                {crumbs[p.id]!.map((crumb, c) => (
                                  <span key={`${crumb.name}-${c}`}>
                                    {c > 0 && (
                                      <span aria-hidden="true" className={styles.crumbSep}>
                                        ›
                                      </span>
                                    )}
                                    {crumb.name}
                                  </span>
                                ))}
                              </span>
                            )}
                            {(isStart || isEnd) && (
                              <span className={styles.stopMeta}>
                                {isStart && (
                                  <span className={styles.tagStart}>Start</span>
                                )}
                                {isEnd && (
                                  <span className={styles.tagEnd}>End</span>
                                )}
                              </span>
                            )}
                          </span>
                        </button>
                      </li>
                    );
                  })}
                </ol>
              </div>

              <div className={styles.actions}>
                {/* Primary: Ask a Question (left) + View Tour (right), 50/50 */}
                <div className={styles.primaryRow}>
                  <button
                    type="button"
                    className={styles.askBtn}
                    onClick={() => setView("inquiry")}
                  >
                    <svg
                      width={16}
                      height={16}
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth={2}
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      aria-hidden="true"
                    >
                      <circle cx="12" cy="12" r="10" />
                      <path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3" />
                      <line x1="12" y1="17" x2="12.01" y2="17" />
                    </svg>
                    Ask a Question
                  </button>
                  <a
                    href={tourLink}
                    target="_blank"
                    rel="noopener noreferrer"
                    className={`tw-inline-flex tw-items-center tw-justify-center tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-border-0 tw-cursor-pointer tw-no-underline tw-transition-colors ${styles.viewTour}`}
                  >
                    View Tour
                  </a>
                </div>

                {/* Secondary: Brochure + Save (heart pulled to the right)
                    (Open-in-Google-Maps lives on the map itself — see mapPane) */}
                <div className={styles.tertiaryRow}>
                  <button
                    type="button"
                    className={styles.tertBtn}
                    onClick={() => setView("brochure")}
                  >
                    <svg
                      width={16}
                      height={16}
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth={1.8}
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      aria-hidden="true"
                    >
                      <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" />
                      <path d="M7 10l5 5 5-5" />
                      <path d="M12 15V3" />
                    </svg>
                    Download Brochure
                  </button>
                  <button
                    type="button"
                    className={`${styles.heartBtn} ${
                      saved ? styles.heartActive : ""
                    }`}
                    onClick={() =>
                      toggle({
                        id: tour.id,
                        slug: tour.slug,
                        name: tour.name,
                        image: tour.image,
                      })
                    }
                    aria-pressed={saved}
                    aria-label={saved ? "Remove from wishlist" : "Save to wishlist"}
                    title={saved ? "Saved" : "Save to wishlist"}
                  >
                    <svg
                      width={19}
                      height={19}
                      viewBox="0 0 24 24"
                      fill={saved ? "currentColor" : "none"}
                      stroke="currentColor"
                      strokeWidth={2}
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      aria-hidden="true"
                    >
                      <path d={HEART_PATH} />
                    </svg>
                  </button>
                </div>
              </div>
            </aside>
        </>

        {/* Form overlay — only this mounts/unmounts on open/close; the map
            above stays mounted, so going back never remounts (crashes) it. */}
        {view !== "route" && (
          <>
            {infoPane}
            <div className={styles.formSide}>
              {view === "inquiry" ? (
                <InquiryForm tourId={tour.id} onBack={() => setView("route")} />
              ) : (
                <BrochureForm
                  tourSlug={tour.slug}
                  onBack={() => setView("route")}
                />
              )}
            </div>
          </>
        )}
      </div>
    </div>,
    document.body,
  );
}
